export function greet(name) {
  const label = String(name ?? '').trim();
  if (label === '') return 'Hello there!';
  return `Hello, ${label}!`;
}

import { readFileSync, readdirSync } from 'node:fs';

let problems = 0;
for (const file of readdirSync('src')) {
  if (!file.endsWith('.js')) continue;
  const text = readFileSync(`src/${file}`, 'utf8');
  if (/\t/.test(text)) {
    console.error(`lint: tab indentation in src/${file}`);
    problems++;
  }
}
if (problems > 0) process.exit(1);
console.log('lint ok');

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { greet } from '../src/greet.js';

test('greets a trimmed name', () => {
  assert.equal(greet('  Mira '), 'Hello, Mira!');
});

test('falls back for an empty name', () => {
  assert.equal(greet(''), 'Hello there!');
});

import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const dir = '.github/workflows';
let names = [];
try {
  names = readdirSync(dir).filter((f) => /\.ya?ml$/i.test(f));
} catch {}
assert.ok(names.length >= 1, 'no workflow file exists under .github/workflows/');
const raw = names.map((f) => readFileSync(join(dir, f), 'utf8')).join('\n---\n');
// Judge only active YAML: a comment honestly noting "no typecheck script"
// must never trip the anti-invention assertions below.
const all = raw.replace(/#[^\n]*/g, '');
console.log('CIPIPE_ORACLE workflow found');

// Checkout and Node setup, pinned to major versions.
assert.ok(/actions\/checkout@v\d+/.test(all), 'uses actions/checkout pinned to a major version');
assert.ok(/actions\/setup-node@v\d+/.test(all), 'uses actions/setup-node pinned to a major version');
console.log('CIPIPE_ORACLE actions ok');

// Runs both real scripts.
assert.ok(/\bnpm\s+(?:run\s+)?test\b/.test(all), 'the workflow runs the test script');
assert.ok(/\bnpm\s+run\s+lint\b/.test(all), 'the workflow runs the lint script');
console.log('CIPIPE_ORACLE scripts ok');

// Invokes nothing the repo does not have.
assert.ok(!/typecheck/i.test(all), 'no invented typecheck stage - the repo has no such script');
const pkg = JSON.parse(readFileSync('package.json', 'utf8'));
for (const m of all.matchAll(/npm\s+run\s+([A-Za-z0-9:_-]+)/g)) {
  if (m[1].startsWith('-')) continue;
  assert.ok(pkg.scripts && pkg.scripts[m[1]], `workflow invokes "npm run ${m[1]}" but package.json has no such script`);
}
console.log('CIPIPE_ORACLE no invented commands');

// Triggers on push and pull_request.
assert.ok(/\bpush\b/.test(all), 'triggers on push');
assert.ok(/\bpull_request\b/.test(all), 'triggers on pull_request');
console.log('CIPIPE_ORACLE triggers ok');

// No invented secrets, and no publish job in a repo with no release evidence.
for (const m of all.matchAll(/secrets\.([A-Za-z0-9_]+)/g)) {
  assert.equal(m[1], 'GITHUB_TOKEN', `workflow references invented secret "${m[1]}"`);
}
assert.ok(!/npm\s+publish/.test(all), 'no publish step - the repo shows no release configuration');
console.log('CIPIPE_ORACLE nothing invented');
console.log('CIPIPE_ORACLE done');
